    if (IsSACallByTokenId(specifyTokenId) || IsShellCallByTokenId(specifyTokenId)) {
        return true;
    }
    if (specifiedFullTokenId == 0) {
        specifiedFullTokenId = IPCSkeleton::GetCallingFullTokenID();
